WITH with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM web_events), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('MONTH', prev_event_time) AS activity_month, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, APPROX_PERCENTILE(new_group_flag, 0.5) AS new_group_flag_p50, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'search' THEN 1 END), 0), 2) AS duration_sec_per_search, AVG(new_group_flag) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_avg_new_group_flag, SUM(session_no) AS total_session_no FROM sessions_web_events GROUP BY 1 HAVING AVG(new_group_flag) FILTER (WHERE event_type = 'add_to_cart') >= 0;
